<template>
<div class="nst-screen payroll-page">
 <header class="payroll-hero"><div><small>PERSONAL Y COMISIONES</small><h2>Planilla y pagos</h2><p>Sueldos, adelantos y comisiones con cuenta de salida e historial.</p></div><button class="btn btn-light" @click="newPerson()">+ Registrar personal</button></header>
 <nav class="payroll-tabs"><a class="btn btn-success" :class="{'disabled': loading || filtersDirty}" :href="API+'planilla/excel?periodo='+encodeURIComponent(period)+'&amp;idAlmacen='+encodeURIComponent(warehouse)+'&amp;buscar='+encodeURIComponent(filter)" target="_blank" rel="noopener">Exportar Excel</a><button v-for="t in tabs" :key="t.id" class="btn" :class="tab===t.id?'btn-info':'btn-outline-info'" @click="tab=t.id">{{t.label}}</button></nav>
 <section class="payroll-panel payroll-filters"><label>Periodo de planilla<input class="form-control" type="month" v-model="period"/></label><label v-if="tab==='comisiones' || tab==='historial'">Desde<input class="form-control" type="date" v-model="from"/></label><label v-if="tab==='comisiones' || tab==='historial'">Hasta<input class="form-control" type="date" v-model="to"/></label><label>Almacén<select class="form-control" v-model="warehouse"><option value="0">Todos</option><option v-for="a in data.almacenes" :key="a.IdAlmacen" :value="a.IdAlmacen">{{a.Almacen}}</option></select></label><button class="btn btn-info" :disabled="loading" @click="load">{{loading?'Cargando…':'Consultar'}}</button><label>Buscar<input class="form-control" v-model="filter" placeholder="Nombre o documento"/></label></section>
 <div v-if="filtersDirty" class="alert alert-info">Filtros modificados. Pulsa Consultar antes de preparar o pagar.</div>
 <div v-if="error" class="alert alert-danger" role="alert">{{error}}</div>
 <section v-if="tab==='planilla' && !filtersDirty && !loading" class="payroll-alerts" aria-live="polite"><div v-if="paymentAlerts.overdue.length" class="alert alert-danger" role="alert"><b>Pagos vencidos: {{paymentAlerts.overdue.length}} · {{money(paymentAlerts.overdue.reduce((s,p)=>s+Number(p.Saldo),0))}}</b><div v-for="p in paymentAlerts.overdue" :key="p.IdPlanilla">{{p.Empleado}} — {{paymentDate(personInfo(p))}} — falta pagar {{money(p.Saldo)}} <button class="btn btn-sm btn-danger" @click="openPay(p)">Pagar</button></div></div><div v-if="paymentAlerts.today.length" class="alert alert-warning" role="alert"><b>Se pagan hoy: {{paymentAlerts.today.length}}</b><div v-for="p in paymentAlerts.today" :key="p.IdPlanilla">{{p.Empleado}} — {{money(p.Saldo)}} <button class="btn btn-sm btn-warning" @click="openPay(p)">Pagar</button></div></div><div v-if="paymentAlerts.unreviewed.length" class="alert alert-danger" role="alert"><b>Fecha de pago cumplida: sueldo pendiente de revisar</b><div v-for="p in paymentAlerts.unreviewed" :key="p.IdEmpleado">{{p.Empleado}} — {{paymentDate(p)}} — sueldo configurado {{money(p.Sueldo)}} <button class="btn btn-sm btn-danger" @click="prepare(p)">Revisar pago</button></div></div><div v-if="paymentAlerts.missing.length" class="alert alert-info"><b>Datos pendientes: {{paymentAlerts.missing.length}} personas</b><div v-for="p in paymentAlerts.missing" :key="p.IdEmpleado">{{p.Empleado}}: {{missingPaymentData(p)}} <button class="btn btn-sm btn-outline-info" @click="newPerson(p)">Completar datos</button></div></div><div v-if="!paymentAlerts.overdue.length && !paymentAlerts.today.length && !paymentAlerts.unreviewed.length && !paymentAlerts.missing.length" class="alert alert-success">Sin alertas de pago para el periodo y los filtros seleccionados.</div></section>
 <section class="payroll-summary"><div><small>{{tab==='comisiones'?'Comisión generada en el rango':'Total confirmado del mes'}}</small><strong>{{money(total)}}</strong></div><div><small>{{tab==='comisiones'?'Comisión pagada del rango':'Ya pagado / adelantos'}}</small><strong>{{money(paid)}}</strong></div><div><small>{{tab==='comisiones'?'Saldo pendiente':'Total que falta pagar'}}</small><strong>{{money(balance)}}</strong></div></section>
 <section class="payroll-panel" v-if="tab==='personal'"><h4>Personal de tienda</h4><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Personal</th><th>Cargo / tienda</th><th>Sueldo mensual</th><th>Fecha de pago</th><th>Cuenta del personal</th><th>Estado</th><th></th></tr></thead><tbody><tr v-for="p in people" :key="p.IdEmpleado"><td><b>{{p.Empleado}}</b><small>{{p.DniRuc}} ? {{p.Telefono || 'Sin teléfono'}}</small></td><td>{{p.Cargo || 'Sin cargo'}}<small>{{storeName(p.IdAlmacen)}}</small></td><td>{{money(p.Sueldo)}}</td><td>{{paymentDate(p)}}<small v-if="p.DiaPago">Cada mes según ingreso: día {{p.DiaPago}}</small></td><td>{{bankLabel(p)}}<small v-if="p.CCI">CCI: {{p.CCI}}</small><small v-if="p.Titular">Titular: {{p.Titular}}</small></td><td>{{Number(p.Activo)?'Activo':'Inactivo'}}</td><td class="payroll-actions"><button class="btn btn-outline-info btn-sm" @click="newPerson(p)">Editar</button><button class="btn btn-info btn-sm" :disabled="!Number(p.Activo) || filtersDirty" @click="prepare(p)">Preparar periodo</button></td></tr><tr v-if="!people.length"><td colspan="7">No hay personal para estos filtros.</td></tr></tbody></table></div></section>
 <section class="payroll-panel" v-if="tab==='planilla'"><h4>¿A quién pagar? · {{period}}</h4><p class="text-muted">Revisa el sueldo y confirma el cálculo del mes. La columna <b>Falta pagar</b> muestra el importe que queda por entregar después de los adelantos y pagos.</p><div v-if="unpreparedPeople.length" class="alert alert-warning"><b>{{unpreparedPeople.length}} personas pendientes de revisar.</b> Sueldos configurados: {{money(unpreparedPeople.reduce((sum,p)=>sum+Number(p.Sueldo || 0),0))}}. Confirma cada cálculo para conocer su importe final.</div><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Persona</th><th>Fecha de pago</th><th>Cuenta del personal</th><th>Sueldo configurado</th><th>Descuentos</th><th>Neto a cobrar</th><th>Ya pagado / adelantos</th><th>Falta pagar</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="p in payroll" :key="p.IdPlanilla"><td><b>{{p.Empleado}}</b><small>{{p.DniRuc}} · Confirmó {{p.UsuarioReg}}</small><button class="btn btn-link btn-sm" @click="newPerson(personInfo(p))">Editar datos</button></td><td>{{paymentDate(personInfo(p))}}<small v-if="personInfo(p).InicioCiclo">Trabajo: {{personInfo(p).InicioCiclo}} al {{personInfo(p).FinCiclo}}</small><small>{{dueStatus(personInfo(p),p.Saldo)}}</small></td><td>{{bankLabel(personInfo(p))}}<small v-if="personInfo(p).CCI">CCI: {{personInfo(p).CCI}}</small></td><td>{{money(personInfo(p).Sueldo)}}<small v-if="Number(p.Detalle.Sueldo)!==Number(personInfo(p).Sueldo)">Sueldo ajustado del mes: {{money(p.Detalle.Sueldo)}}</small><small v-if="Number(p.Detalle.Comision)>0">Comisión: {{money(p.Detalle.Comision)}}</small></td><td>{{money(p.Detalle.Descuentos)}}</td><td>{{money(p.Neto)}}</td><td>{{money(p.Pagado)}}</td><td class="payroll-amount-due"><b>{{money(p.Saldo)}}</b></td><td><span class="payroll-status" :class="Number(p.Saldo)>0?'is-due':'is-paid'">{{Number(p.Saldo)>0?'PENDIENTE DE PAGO':'PAGADO / SIN SALDO'}}</span></td><td class="payroll-actions"><button class="btn btn-outline-info btn-sm" @click="viewPeriod(p)">Ver cálculo</button><button class="btn btn-outline-info btn-sm" @click="openSlip(p)">Boleta PDF</button><button class="btn btn-warning btn-sm" :disabled="Number(p.Saldo)<=0 || filtersDirty" @click="startAdvance(p)">Dar adelanto</button><button class="btn btn-outline-info btn-sm" :disabled="filtersDirty" @click="showAdvances(p)">Ver adelantos</button><button class="btn btn-success btn-sm" :disabled="Number(p.Saldo)<=0 || filtersDirty" @click="openPay(p)">Pagar {{money(p.Saldo)}}</button></td></tr><tr v-for="p in unpreparedPeople" :key="'pending-'+p.IdEmpleado"><td><b>{{p.Empleado}}</b><small>{{p.DniRuc}}</small><button class="btn btn-link btn-sm" @click="newPerson(p)">Editar datos</button></td><td>{{paymentDate(p)}}<small v-if="p.InicioCiclo">Trabajo: {{p.InicioCiclo}} al {{p.FinCiclo}}</small><small>{{dueStatus(p)}}</small></td><td>{{bankLabel(p)}}<small v-if="p.CCI">CCI: {{p.CCI}}</small></td><td>{{Number(p.Sueldo)>0?money(p.Sueldo):'Sin configurar'}}</td><td>—</td><td>Por calcular</td><td>—</td><td>Por confirmar</td><td><span class="payroll-status is-review">{{Number(p.Sueldo)>0?'REVISAR MES':'CONFIGURAR SUELDO'}}</span></td><td><button v-if="Number(p.Sueldo)>0" class="btn btn-info btn-sm" :disabled="filtersDirty || loading" @click="prepare(p)">Revisar y calcular pago</button><button v-if="Number(p.Sueldo)>0" class="btn btn-warning btn-sm" :disabled="filtersDirty || loading" @click="startAdvance(p)">Dar adelanto</button><button class="btn btn-outline-info btn-sm" :disabled="filtersDirty" @click="showAdvances(p)">Ver adelantos</button><button v-if="Number(p.Sueldo)<=0" class="btn btn-outline-info btn-sm" @click="newPerson(p)">Configurar sueldo</button></td></tr><tr v-if="!payroll.length && !unpreparedPeople.length"><td colspan="10">No hay personal para estos filtros.</td></tr></tbody></table></div></section>
 <section class="payroll-panel" v-if="tab==='comisiones'"><h4>Comisiones de clientes · {{from}} al {{to}}</h4><p class="text-muted">Generadas por ventas del rango. Los pagos se aplican a cada venta, aunque se paguen en otra fecha.</p><div class="table-responsive"><table class="table table-hover"><thead><tr><th>DNI/RUC</th><th>Comisionista</th><th>Generada</th><th>Pagada</th><th>Pendiente</th><th></th></tr></thead><tbody><tr v-for="c in clients" :key="c.IdCliente"><td>{{c.DniRuc}}</td><td><b>{{c.Cliente}}</b></td><td>{{money(c.Generada)}}</td><td>{{money(c.Pagada)}}</td><td><b>{{money(c.Pendiente)}}</b></td><td class="payroll-actions"><button class="btn btn-outline-info btn-sm" @click="openCommission(c)">Ver ventas</button><button class="btn btn-success btn-sm" :disabled="Number(c.Pendiente)<=0 || filtersDirty" @click="openPay(c,true)">Pagar comisión</button></td></tr><tr v-if="!clients.length"><td colspan="6">No hay comisiones para este rango.</td></tr></tbody></table></div></section>
 <section class="payroll-panel" v-if="tab==='historial'"><div class="payroll-heading"><h4>Historial de pagos ? rango de fechas</h4><button class="btn btn-outline-info btn-sm" @click="printHistory">Imprimir</button></div><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Fecha</th><th>Beneficiario / periodo</th><th>Concepto</th><th>Cuenta de salida</th><th>Importe</th><th>Referencia</th><th>Registr?</th><th></th></tr></thead><tbody><tr v-for="p in payments" :key="p.IdPago" :class="isVoided(p)?'text-muted':''"><td>{{p.Fecha}}</td><td>{{p.Empleado || p.Cliente}}<small>{{p.Periodo}}</small></td><td>{{p.Tipo}}<small v-if="isVoided(p)">ANULADO ? {{p.UsuarioAnula}}</small></td><td>{{p.Cuenta}}</td><td>{{money(p.Importe)}}</td><td>{{p.Referencia}}</td><td>{{p.UsuarioReg}}</td><td><button class="btn btn-outline-danger btn-sm" v-if="!isVoided(p)" :disabled="saving" @click="voidPay(p)">Anular</button></td></tr><tr v-if="!payments.length"><td colspan="8">Sin pagos en el rango.</td></tr></tbody></table></div></section>
 <b-modal v-model="personModal" title="Personal de tienda" size="lg" hide-footer modal-class="nst-dialog"><form @submit.prevent="savePerson"><div class="payroll-form"><label>Nombre<input required maxlength="200" class="form-control" v-model="person.Empleado"/></label><label>DNI / documento<input required maxlength="50" class="form-control" v-model="person.DniRuc"/></label><label>Teléfono<input type="tel" class="form-control" v-model="person.Telefono"/></label><label>Cargo<input maxlength="100" class="form-control" v-model="person.Cargo"/></label><label>Tienda<select class="form-control" v-model="person.IdAlmacen"><option value="0">Sin asignar</option><option v-for="a in data.almacenes" :key="a.IdAlmacen" :value="a.IdAlmacen">{{a.Almacen}}</option></select></label><label>Sueldo mensual (S/)<input type="number" min="0" step=".01" required class="form-control" v-model="person.Sueldo"/></label><label>Fecha de ingreso<input type="date" class="form-control" v-model="person.FechaIngreso"/></label><label>Día de pago según ingreso<input class="form-control" :value="person.FechaIngreso ? Number(person.FechaIngreso.slice(8,10)) : 'Registra la fecha de ingreso'" readonly/><small>El primer sueldo vence al cumplir un mes. En meses cortos, vence el último día disponible.</small></label><label>Banco del trabajador<input maxlength="80" class="form-control" v-model="person.Banco" placeholder="BCP, BBVA, Interbank..."/></label><label>Número de cuenta del trabajador<input maxlength="80" class="form-control" v-model="person.NumeroCuenta" autocomplete="off"/></label><label>CCI (20 dígitos)<input maxlength="20" pattern="[0-9]{20}" inputmode="numeric" class="form-control" v-model="person.CCI" autocomplete="off"/></label><label>Titular de la cuenta<input maxlength="150" class="form-control" v-model="person.Titular"/></label><label><input type="checkbox" v-model="person.Activo"/> Personal activo</label></div><button type="button" class="btn btn-outline-info" @click="advancedPerson=!advancedPerson">{{advancedPerson?'Ocultar':'Mostrar'}} descuentos y beneficios</button><div v-if="advancedPerson" class="payroll-form payroll-advanced"><label>Régimen<select class="form-control" v-model="person.Regimen"><option value="GENERAL">General</option><option value="PEQUENA">Pequeña empresa REMYPE</option><option value="MICRO">Microempresa REMYPE</option></select></label><label>Pensión<select class="form-control" v-model="person.Pension"><option value="NINGUNO">Sin descuento configurado</option><option>ONP</option><option>AFP</option></select></label><label v-if="person.Pension==='AFP'">AFP<input class="form-control" v-model="person.AFP" placeholder="Administradora y modalidad"/></label></div><div class="payroll-modal-footer"><button class="btn btn-success" :disabled="saving">Guardar personal</button><button type="button" class="btn btn-secondary" @click="personModal=false">Cerrar</button></div></form></b-modal>
 <b-modal v-model="periodModal" :title="(advanceMode ? 'Preparar adelanto - ' : 'Liquidación - ')+selectedName+' - '+period" size="lg" hide-footer modal-class="nst-dialog"><form @submit.prevent="savePeriod"><div v-if="advanceMode" class="alert alert-info">Conserva el sueldo mensual completo y elige la cuenta. El importe del adelanto se ingresa en el siguiente paso.</div><div class="payroll-form"><label>{{advanceMode?'Sueldo mensual completo (no es el adelanto)':'Sueldo del periodo (S/)'}}<input required type="number" min="0" step=".01" class="form-control" v-model="detail.Sueldo" :disabled="readOnly || advanceMode || !salaryAdjustment"/><button v-if="!readOnly && !advanceMode" type="button" class="btn btn-link btn-sm" @click="salaryAdjustment=!salaryAdjustment">{{salaryAdjustment?'Bloquear sueldo':'Ajustar sueldo de este periodo'}}</button></label><label v-if="salaryAdjustment || detail.MotivoCambioSueldo">Motivo del ajuste del sueldo<input :required="salaryAdjustment" maxlength="500" class="form-control" v-model="detail.MotivoCambioSueldo" :disabled="readOnly"/></label><label v-if="!advanceMode">Comisión del personal (S/)<input type="number" min="0" step=".01" class="form-control" v-model="detail.Comision" :disabled="readOnly"/></label></div><button v-if="!advanceMode" type="button" class="btn btn-outline-info" @click="advanced=!advanced">{{advanced?'Ocultar':'Mostrar'}} descuentos y beneficios</button><section v-if="advanced" class="payroll-advanced"><p class="text-muted">Revisa las bases y los importes según el régimen y el periodo. CTS y gratificación no forman parte de la base pensionable. Los aportes del empleador no se descuentan al trabajador.</p><div class="payroll-form"><label>Régimen<select class="form-control" v-model="detail.Regimen" :disabled="readOnly"><option value="GENERAL">General</option><option value="PEQUENA">Pequeña REMYPE</option><option value="MICRO">Micro REMYPE</option></select></label><label>Pensión<select class="form-control" v-model="detail.Pension" :disabled="readOnly"><option value="NINGUNO">Sin descuento configurado</option><option>ONP</option><option>AFP</option></select></label><label>Base pensionable revisada<input type="number" min="0" step=".01" class="form-control" v-model="detail.BasePension" :disabled="readOnly"/></label><div><small>Aporte {{detail.Pension}}</small><strong>{{money(pensionAmount)}}</strong><small>ONP 13% ? AFP aporte al fondo 10%</small></div><label v-if="detail.Pension==='AFP'">Seguro AFP (importe del periodo)<input type="number" min="0" step=".01" class="form-control" v-model="detail.SeguroAFP" :disabled="readOnly"/></label><label v-if="detail.Pension==='AFP'">Comisión AFP sobre remuneración (importe)<input type="number" min="0" step=".01" class="form-control" v-model="detail.ComisionAFP" :disabled="readOnly"/></label><label v-for="f in advancedFields" :key="f.key">{{f.label}} (S/)<input type="number" min="0" step=".01" class="form-control" v-model="detail[f.key]" :disabled="readOnly"/></label></div><details v-if="!readOnly"><summary>Asistente de CTS y gratificación</summary><p>Usa remuneración computable revisada y tiempo computable. Los resultados se aplican solo al pulsar el botón.</p><div class="payroll-form"><label>Base computable del beneficio<input class="form-control" type="number" min="0" step=".01" v-model="benefitBase"/></label><label>?ltima gratificación para CTS<input class="form-control" type="number" min="0" step=".01" v-model="lastGrati"/></label><label>Días computables CTS (máx. 180)<input class="form-control" type="number" min="0" max="180" v-model="ctsDays"/></label><label>Meses completos de gratificación (0?6)<input class="form-control" type="number" min="0" max="6" step="1" v-model="gratiMonths"/></label><label>Bonificación<select class="form-control" v-model="bonusRate"><option value="9">EsSalud 9%</option><option value="6.75">EPS 6.75%</option></select></label></div><button type="button" class="btn btn-outline-info btn-sm" @click="calculateBenefits">Aplicar cálculo revisado</button><p class="text-muted">En microempresa el asistente no genera CTS ni gratificación. En pequeña empresa usa el factor ½; revisa topes, antigüedad y condición REMYPE.</p></details><p><a href="https://www.sbs.gob.pe/app/spp/empleadores/comisiones_spp/Paginas/comision_prima.aspx" target="_blank" rel="noopener">Consultar tasas AFP en SBS</a> ? <a href="https://www.gob.pe/7944" target="_blank" rel="noopener">ONP</a> ? <a href="https://www.gob.pe/institucion/mtpe/informes-publicaciones/2206240-guia-sobre-el-regimen-laboral-de-la-micro-y-pequena-empresa" target="_blank" rel="noopener">Regímenes laborales</a></p></section><label v-if="!advanceMode">Observaciones<textarea maxlength="1000" class="form-control" v-model="detail.Observacion" :disabled="readOnly"/></label><div v-if="!advanceMode" class="payroll-summary"><div><small>Ingresos</small><strong>{{money(preview.income)}}</strong></div><div><small>Descuentos</small><strong>{{money(preview.deductions)}}</strong></div><div><small>Neto</small><strong>{{money(preview.net)}}</strong></div></div><label v-if="!readOnly"><input type="checkbox" v-model="reviewed" required/> Revis? sueldo, comisión, descuentos y beneficios del periodo.</label><section v-if="!readOnly" class="payroll-payment-account"><label for="liquidationAccount">Cuenta de salida para el pago</label><select id="liquidationAccount" class="form-control" v-model="liquidationAccount"><option value="">Seleccione una cuenta</option><option v-for="c in data.cuentas" :key="c.IdCuenta" :value="c.IdCuenta">{{c.Cuenta}}</option></select><small>Selecciona Caja Principal, Banco BCP u otra cuenta registrada. Podrás revisar y confirmar el pago en el siguiente paso.</small></section><div class="payroll-modal-footer"><button v-if="!readOnly" type="button" class="btn btn-info" :disabled="saving || !reviewed || preview.net<=0 || !liquidationAccount" @click="savePeriod(true)">{{advanceMode?'Continuar con adelanto':'Guardar y preparar pago'}}</button><button v-if="!readOnly && !advanceMode" class="btn btn-success" :disabled="saving || !reviewed || preview.net<0">Confirmar cálculo del mes</button><button type="button" class="btn btn-secondary" @click="periodModal=false">Cerrar</button></div></form></b-modal>
 <b-modal v-model="payModal" title="Registrar pago" hide-footer modal-class="nst-dialog"><form @submit.prevent="savePay"><h5>{{payName}}</h5><div class="alert alert-info">Saldo disponible: {{money(payBalance)}}</div><label>Concepto<select class="form-control" v-model="pay.Tipo" :disabled="pay.Tipo==='COMISION_CLIENTE'"><option v-for="t in payTypes" :key="t" :value="t">{{t}}</option><option v-if="pay.Tipo==='COMISION_CLIENTE'">COMISION_CLIENTE</option></select></label><section v-if="payRecipient" class="payroll-destination"><b>Cuenta de destino del trabajador</b><p>{{bankLabel(payRecipient)}}</p><small v-if="payRecipient.CCI">CCI: {{payRecipient.CCI}}</small><small v-if="payRecipient.Titular">Titular: {{payRecipient.Titular}}</small><small>Fecha programada: {{paymentDate(payRecipient)}}</small></section><label>Cuenta de salida de la empresa<select required class="form-control" v-model="pay.IdCuenta"><option value="">Seleccione una cuenta</option><option v-for="c in data.cuentas" :key="c.IdCuenta" :value="c.IdCuenta">{{c.Cuenta}}</option></select></label><div class="payroll-form"><label>Fecha del pago<input required type="date" class="form-control" v-model="pay.Fecha"/></label><label>Importe (S/)<input required type="number" min=".01" step=".01" :max="payBalance" class="form-control" v-model="pay.Importe"/></label></div><label>Número de operación / referencia<input maxlength="150" class="form-control" v-model="pay.Referencia"/></label><p class="text-muted">Se registrar? un egreso en Caja y Banco desde la cuenta seleccionada.</p><div class="payroll-modal-footer"><button class="btn btn-success" :disabled="saving">{{saving?'Guardando…':'Confirmar pago'}}</button><button type="button" class="btn btn-secondary" @click="payModal=false">Cancelar</button></div></form></b-modal>
 <b-modal :visible="!!commissionDetail" @hide="commissionDetail=null" title="Productos y comprobantes de la comisión" size="lg" hide-footer modal-class="nst-dialog commission-sales-modal"><div v-if="commissionDetail"><h5>{{commissionDetail.Cliente}}</h5><p class="text-muted">{{from}} al {{to}}</p><div v-if="commissionLoading" role="status">Cargando productos vendidos...</div><template v-else><div class="commission-counts"><span><b>{{commissionCounts.boletas}}</b> Boletas</span><span><b>{{commissionCounts.facturas}}</b> Facturas</span><span><b>{{commissionCounts.otros}}</b> Otros comprobantes</span><span><b>{{commissionCounts.unidades}}</b> Unidades vendidas</span></div><article v-for="d in commissionDetail.Documentos" :key="d.idDocVenta" class="commission-sale"><header><div><strong>{{d.TipoDoc || (d.CodSunat==='01'?'Factura':d.CodSunat==='03'?'Boleta':'Comprobante')}} {{d.Serie}}-{{d.Numero}}</strong><small>{{d.FechaDoc}} · Venta #{{d.idDocVenta}}</small></div><div>Total vendido <b>{{money(d.TotalVenta)}}</b></div></header><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Código</th><th>Producto vendido</th><th>Cantidad</th><th>Precio unitario</th><th>Descuento</th><th>Total</th></tr></thead><tbody><tr v-for="p in d.Productos" :key="p.IdDocVentaDet"><td>{{p.CodigoBarra || p.IdProducto}}</td><td class="commission-product-name"><b>{{p.Producto}}</b><small v-if="p.Descripcion">{{p.Descripcion}}</small></td><td>{{p.Cantidad}}</td><td>{{money(p.Precio)}}</td><td>{{money(p.Descuento)}}</td><td><b>{{money(p.Total)}}</b></td></tr><tr v-if="!d.Productos || !d.Productos.length"><td colspan="6">Sin detalle de productos disponible.</td></tr></tbody></table></div><footer><span>Comisión generada <b>{{money(d.Generada)}}</b></span><span>Pagada <b>{{money(d.Pagada)}}</b></span><span>Pendiente <b>{{money(d.Pendiente)}}</b></span></footer></article><p v-if="!commissionDetail.Documentos.length">No hay ventas para este rango.</p></template></div></b-modal>
 <b-modal :visible="!!advanceDetail" @hide="advanceDetail=null" title="Adelantos del personal" size="lg" hide-footer modal-class="nst-dialog"><div v-if="advanceDetail"><h5>{{advanceDetail.Empleado}}</h5><p>Periodo: <b>{{advanceDetail.Periodo}}</b></p><div v-if="advancesLoading" role="status">Cargando adelantos...</div><div v-else-if="advancesError" class="alert alert-danger">{{advancesError}}</div><template v-else><div class="alert alert-info">Total de adelantos vigentes del mes: <b>{{money(advanceTotal)}}</b></div><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Fecha del adelanto</th><th>Importe</th><th>Cuenta de salida</th><th>Referencia</th><th>Registrado por</th><th>Estado</th></tr></thead><tbody><tr v-for="a in advanceRows" :key="a.IdPago" :class="isVoided(a)?'text-muted':''"><td>{{a.Fecha.split('-').reverse().join('/')}}</td><td><b>{{money(a.Importe)}}</b></td><td>{{a.Cuenta}}</td><td>{{a.Referencia || '—'}}</td><td>{{a.UsuarioReg}}</td><td>{{isVoided(a)?'Anulado':'Vigente'}}<small v-if="isVoided(a)&&a.UsuarioAnula">Por {{a.UsuarioAnula}}</small></td></tr><tr v-if="!advanceRows.length"><td colspan="6">No tiene adelantos registrados para este mes.</td></tr></tbody></table></div></template></div></b-modal>
 <b-modal v-model="slipModal" title="Boleta de pago laboral" size="lg" hide-footer modal-class="nst-dialog"><div v-if="slipLoading" role="status">Cargando datos de la boleta...</div><div v-if="slipError" class="alert alert-danger" role="alert">{{slipError}}</div><form v-if="slipContext && !slipLoading" @submit.prevent="issueSlip"><h5>{{slipContext.planilla.Empleado}} · {{slipContext.planilla.Periodo}}</h5><p>{{slipContext.empresa.RAZONSOCIAL}} · RUC {{slipContext.empresa.RUC}}</p><div class="alert alert-info">Gerente general: <b>BLANCA MARTINEZ BRAVO</b>. El PDF tendrá espacios para firma y sello.</div><h6>Datos laborales</h6><div class="payroll-form"><label>Tipo de documento<select required class="form-control" v-model="slipLegal.TipoDocumento"><option>DNI</option><option>CE</option><option>PASAPORTE</option><option>PTP</option><option>OTRO</option></select></label><label>Categoría del trabajador<input required maxlength="250" class="form-control" v-model="slipLegal.Categoria" placeholder="Empleado, obrero..."/></label><label v-if="slipContext.planilla.Detalle.Pension==='AFP'">CUSPP<input required maxlength="30" class="form-control" v-model="slipLegal.CUSPP"/></label><label v-else>Código de asegurado (si corresponde)<input maxlength="50" class="form-control" v-model="slipLegal.CodigoAsegurado"/></label><label>Domicilio<input maxlength="250" class="form-control" v-model="slipLegal.Direccion"/></label></div><button type="button" class="btn btn-outline-info btn-sm" @click="slipMore=!slipMore">{{slipMore?'Ocultar':'Mostrar'}} datos adicionales</button><div v-if="slipMore" class="payroll-form"><label>Sexo<select class="form-control" v-model="slipLegal.Sexo"><option value="">Sin registrar</option><option>Femenino</option><option>Masculino</option></select></label><label>Nacionalidad<input maxlength="80" class="form-control" v-model="slipLegal.Nacionalidad"/></label><label>Fecha de nacimiento<input type="date" class="form-control" v-model="slipLegal.FechaNacimiento"/></label><label>Fecha de cese (si corresponde)<input type="date" class="form-control" v-model="slipLegal.FechaCese"/></label></div><h6 class="mt-3">Asistencia real del periodo</h6><p class="text-muted">Completa según el registro de asistencia. Escribe 0 cuando no corresponda.</p><div class="payroll-form"><label>Días efectivamente laborados<input required type="number" min="0" max="31" step="1" class="form-control" v-model="slipAttendance.DiasLaborados"/></label><label>Días subsidiados<input required type="number" min="0" max="31" step="1" class="form-control" v-model="slipAttendance.DiasSubsidiados"/></label><label>Días no laborados y no subsidiados<input required type="number" min="0" max="31" step="1" class="form-control" v-model="slipAttendance.DiasNoLaborados"/></label><label>Horas ordinarias<input required type="number" min="0" max="744" step=".01" class="form-control" v-model="slipAttendance.HorasOrdinarias"/></label><label>Horas en sobretiempo<input required type="number" min="0" max="744" step=".01" class="form-control" v-model="slipAttendance.HorasExtras"/></label><label><input type="checkbox" v-model="slipHasVacation" @change="slipError=''"/> Registrar vacaciones en esta boleta</label><label v-if="slipHasVacation">Salida de vacaciones<input :required="slipHasVacation" type="date" class="form-control" v-model="slipAttendance.VacacionesDesde"/></label><label v-if="slipHasVacation">Retorno de vacaciones<input :required="slipHasVacation" :min="slipAttendance.VacacionesDesde || undefined" type="date" class="form-control" v-model="slipAttendance.VacacionesHasta"/></label></div><section v-if="Number(slipContext.planilla.Detalle.AporteEmpleador)>0" class="payroll-advanced"><h6>Aportes a cargo del empleador</h6><p>Total registrado: {{money(slipContext.planilla.Detalle.AporteEmpleador)}}. Distribuye ese total por concepto.</p><div class="payroll-form"><label v-for="a in ['EsSalud','VidaLey','SCTR','Otros']" :key="a">{{a}} (S/)<input type="number" min="0" step=".01" required class="form-control" v-model="slipAttendance.Aportes[a]"/></label><label v-if="Number(slipAttendance.Aportes.Otros)>0">Detalle de otros aportes<input required maxlength="250" class="form-control" v-model="slipLegal.DetalleOtrosAportes"/></label></div></section><label v-if="Number(slipContext.planilla.Detalle.OtrosDescuentos)>0">Detalle de otros descuentos<input required maxlength="250" class="form-control" v-model="slipLegal.DetalleOtrosDescuentos"/></label><div class="payroll-summary"><div><small>Neto del periodo</small><strong>{{money(slipContext.planilla.Neto)}}</strong></div><div><small>Pagos registrados</small><strong>{{money(slipContext.pagos.reduce((s,p)=>s+Number(p.Importe),0))}}</strong></div></div><label><input required type="checkbox" v-model="slipReviewed"/> Verifiqué los datos laborales, asistencia e importes de esta boleta.</label><p class="text-muted">Conserva la constancia de pago y entrega. El PDF no incluye una firma digital ni envía declaraciones a SUNAT.</p><div v-if="slipError" class="alert alert-danger" role="alert" aria-live="assertive">{{slipError}}</div><div class="payroll-modal-footer"><button type="submit" class="btn btn-info" :disabled="saving || !slipReviewed">{{saving?'Generando...':slipContext.boletas.length?'Generar nueva versión PDF':'Generar boleta PDF'}}</button><button type="button" class="btn btn-secondary" @click="slipModal=false">Cerrar</button></div><section v-if="slipContext.boletas.length" class="payroll-advanced"><h6>Boletas guardadas</h6><div v-for="b in slipContext.boletas" :key="b.IdBoleta"><a :href="slipUrl(b.IdBoleta)" target="_blank" rel="noopener">Abrir PDF #{{b.IdBoleta}} - versión {{b.Version}}</a><small> · {{b.FechaReg}} · {{b.UsuarioReg}}</small></div></section></form></b-modal>
</div></template>
<script>
import config from '@/store/config.js';
const number=v=>Number(v)||0;
export default {props:{initialTab:{default:'planilla'}},data(){const now=this.$moment();return {API:config.API,tab:this.initialTab,tabs:[{id:'planilla',label:'Planilla'},{id:'personal',label:'Personal'},{id:'comisiones',label:'Comisiones de clientes'},{id:'historial',label:'Historial de pagos'}],period:now.format('YYYY-MM'),from:now.clone().startOf('month').format('YYYY-MM-DD'),to:now.format('YYYY-MM-DD'),warehouse:'0',filter:'',applied:'',data:{personal:[],planilla:[],pagos:[],cuentas:[],almacenes:[]},commissions:[],loading:false,saving:false,error:'',csrf:'',personModal:false,person:{},advancedPerson:false,periodModal:false,advanceMode:false,salaryAdjustment:false,liquidationAccount:'',detail:{},selectedEmployee:0,selectedName:'',advanced:false,readOnly:false,reviewed:false,payModal:false,pay:{},payName:'',payRecipient:null,payBalance:0,commissionDetail:null,commissionLoading:false,slipModal:false,slipLoading:false,slipContext:null,slipLegal:{},slipAttendance:{},slipReviewed:false,slipError:'',slipMore:false,slipHasVacation:false,advanceDetail:null,advanceRows:[],advancesLoading:false,advancesError:'',benefitBase:0,lastGrati:0,ctsDays:180,gratiMonths:6,bonusRate:9,advancedFields:[{key:'Asignacion',label:'Asignación familiar / remunerativa'},{key:'OtrosIngresos',label:'Otros ingresos remunerativos'},{key:'OtrosDescuentos',label:'Otros descuentos'},{key:'RentaQuinta',label:'Retención quinta categoría revisada'},{key:'CTS',label:'CTS a depositar'},{key:'Gratificacion',label:'Gratificación'},{key:'BonoGratificacion',label:'Bonificación extraordinaria'},{key:'Vacaciones',label:'Vacaciones / truncas revisadas'},{key:'AporteEmpleador',label:'Aporte empleador (informativo)'}],payTypes:['SUELDO','ADELANTO','COMISION','CTS','GRATIFICACION','VACACIONES']};},mounted(){this.load();},computed:{advanceTotal(){return this.advanceRows.filter(p=>!this.isVoided(p)).reduce((s,p)=>s+number(p.Importe),0);},paymentAlerts(){const today=this.$moment().format('YYYY-MM-DD');const due=this.payroll.filter(p=>Number(p.Saldo)>0&&this.personInfo(p).FechaPagoPeriodo);return {overdue:due.filter(p=>this.personInfo(p).FechaPagoPeriodo<today),today:due.filter(p=>this.personInfo(p).FechaPagoPeriodo===today),unreviewed:this.unpreparedPeople.filter(p=>p.FechaPagoPeriodo&&p.FechaPagoPeriodo<=today&&Number(p.Sueldo)>0),missing:this.people.filter(p=>Number(p.Activo)&&(!Number(p.Sueldo)||!p.FechaIngreso||!p.Banco||(!p.NumeroCuenta&&!p.CCI)))};},unpreparedPeople(){const ids=new Set(this.data.planilla.map(p=>String(p.IdEmpleado)));return this.people.filter(p=>number(p.Activo)&&!ids.has(String(p.IdEmpleado)));},commissionCounts(){const docs=this.commissionDetail&&this.commissionDetail.Documentos||[];return {boletas:docs.filter(d=>d.CodSunat==='03').length,facturas:docs.filter(d=>d.CodSunat==='01').length,otros:docs.filter(d=>!['01','03'].includes(d.CodSunat)).length,unidades:docs.reduce((sum,d)=>sum+(d.Productos||[]).reduce((n,p)=>n+number(p.Cantidad),0),0)};},balance(){return this.tab==='comisiones'?this.clients.reduce((s,p)=>s+number(p.Pendiente),0):this.payroll.reduce((s,p)=>s+number(p.Saldo),0);},filtersDirty(){return this.applied!==JSON.stringify([this.period,this.from,this.to,String(this.warehouse)]);},people(){return this.data.personal.filter(p=>this.matches(p.Empleado+' '+p.DniRuc)&&(!number(this.warehouse)||number(p.IdAlmacen)===number(this.warehouse)));},payroll(){return this.data.planilla.filter(p=>this.matches(p.Empleado+' '+p.DniRuc)&&this.personInWarehouse(p));},clients(){return this.commissions.filter(c=>this.matches(c.Cliente+' '+c.DniRuc));},payments(){return this.data.pagos.filter(p=>this.matches((p.Empleado||p.Cliente)+' '+p.Referencia)&&(p.IdPlanilla?this.personInWarehouse(p):(!number(this.warehouse)||String(p.Almacenes||'').split(',').includes(String(this.warehouse)))));},total(){return this.tab==='comisiones'?this.clients.reduce((s,p)=>s+number(p.Generada),0):this.payroll.reduce((s,p)=>s+number(p.Neto),0);},paid(){return this.tab==='comisiones'?this.clients.reduce((s,p)=>s+number(p.Pagada),0):this.payroll.reduce((s,p)=>s+number(p.Pagado),0);},pensionAmount(){return number(this.detail.BasePension)*(this.detail.Pension==='ONP'?.13:this.detail.Pension==='AFP'?.10:0);},preview(){const d=this.detail;const income=['Sueldo','Comision','Asignacion','OtrosIngresos','CTS','Gratificacion','BonoGratificacion','Vacaciones'].reduce((s,k)=>s+number(d[k]),0);const deductions=this.pensionAmount+number(d.OtrosDescuentos)+number(d.RentaQuinta)+(d.Pension==='AFP'?number(d.SeguroAFP)+number(d.ComisionAFP):0);return {income,deductions,net:income-deductions};}},methods:{validateSlipVacation(){if(!this.slipHasVacation)return '';const a=this.slipAttendance.VacacionesDesde,b=this.slipAttendance.VacacionesHasta;if(!a||!b)return 'Completa salida y retorno de vacaciones, o desactiva Registrar vacaciones.';if(b<a)return 'El retorno de vacaciones no puede ser anterior a la salida. Revisa las fechas.';return '';},async openSlip(p){this.slipModal=true;this.slipLoading=true;this.slipContext=null;this.slipError='';this.slipReviewed=false;this.slipMore=false;this.slipHasVacation=false;try{const res=await this.axios.get(this.API+'planilla/boleta/datos',{params:{IdPlanilla:p.IdPlanilla}});this.slipContext=res.data;const worker=res.data.planilla;this.slipLegal=Object.assign({TipoDocumento:'DNI',Categoria:'EMPLEADO',CUSPP:'',CodigoAsegurado:'',Direccion:worker.Direccion||'',Sexo:'',Nacionalidad:'',FechaNacimiento:'',FechaCese:'',DetalleOtrosDescuentos:'',DetalleOtrosAportes:''},worker.Laborales||{});this.slipAttendance={DiasLaborados:'',DiasSubsidiados:'',DiasNoLaborados:'',HorasOrdinarias:'',HorasExtras:'',VacacionesDesde:'',VacacionesHasta:'',Aportes:{EsSalud:0,VidaLey:0,SCTR:0,Otros:0}};}catch(e){this.slipError=e.response&&e.response.data.error||'No se pudo cargar la boleta.';}finally{this.slipLoading=false;}},slipUrl(id){return this.API+'planilla/boleta/'+id+'/pdf';},async issueSlip(){if(this.saving||!this.slipReviewed||!this.slipContext)return;const vacationError=this.validateSlipVacation();if(vacationError){this.slipError=vacationError;this.$toasted.error(vacationError);return;}const attendance=Object.assign({},this.slipAttendance);if(!this.slipHasVacation){attendance.VacacionesDesde='';attendance.VacacionesHasta='';}const popup=window.open('','_blank');this.saving=true;this.slipError='';try{const res=await this.axios.post(this.API+'planilla/boleta/emitir',{IdPlanilla:this.slipContext.planilla.IdPlanilla,Laborales:this.slipLegal,Asistencia:attendance,_csrf:this.csrf});const url=this.slipUrl(res.data.IdBoleta);if(popup)popup.location.href=url;else this.$toasted.show('Boleta guardada. Abrela desde la lista de versiones.');const updated=await this.axios.get(this.API+'planilla/boleta/datos',{params:{IdPlanilla:this.slipContext.planilla.IdPlanilla}});this.slipContext=updated.data;this.$toasted.success('Boleta generada y guardada');}catch(e){if(popup)popup.close();this.slipError=e.response&&e.response.data.error||'No se pudo generar la boleta.';this.$toasted.error(this.slipError);}finally{this.saving=false;}},async showAdvances(p){const selected={IdEmpleado:p.IdEmpleado,Empleado:p.Empleado,Periodo:this.period};this.advanceDetail=selected;this.advanceRows=[];this.advancesError='';this.advancesLoading=true;try{const res=await this.axios.get(this.API+'planilla/adelantos',{params:{IdEmpleado:p.IdEmpleado,Periodo:selected.Periodo}});if(this.advanceDetail===selected)this.advanceRows=res.data;}catch(e){if(this.advanceDetail===selected)this.advancesError=e.response&&e.response.data.error||'No se pudieron cargar los adelantos.';}finally{if(this.advanceDetail===selected)this.advancesLoading=false;}},startAdvance(p){const row=p.IdPlanilla?p:this.data.planilla.find(x=>String(x.IdEmpleado)===String(p.IdEmpleado));if(row){this.openPay(row);this.pay.Tipo='ADELANTO';return;}this.prepare(p);this.advanceMode=true;this.advanced=false;},missingPaymentData(p){const missing=[];if(!Number(p.Sueldo))missing.push('sueldo');if(!p.FechaIngreso)missing.push('fecha de ingreso');if(!p.Banco||(!p.NumeroCuenta&&!p.CCI))missing.push('cuenta bancaria');return missing.join(', ');},personInfo(p){return this.data.personal.find(x=>String(x.IdEmpleado)===String(p.IdEmpleado))||{};},bankLabel(p){return [p.Banco,p.NumeroCuenta].filter(Boolean).join(' - ')||'Sin cuenta registrada';},paymentDate(p){if(!p.FechaPagoPeriodo){if(p.FechaPrimerPago)return 'Primer pago: '+p.FechaPrimerPago.split('-').reverse().join('/');return 'Falta fecha de ingreso';}return new Intl.DateTimeFormat('es-PE',{weekday:'long',day:'2-digit',month:'2-digit',year:'numeric',timeZone:'UTC'}).format(new Date(p.FechaPagoPeriodo+'T12:00:00Z'));},dueStatus(p,saldo){if(saldo!==undefined&&Number(saldo)<=0)return 'Sin saldo pendiente';if(!p.FechaPagoPeriodo)return p.FechaPrimerPago?'Primer sueldo al cumplir un mes':'Registrar fecha de ingreso';const today=this.$moment().format('YYYY-MM-DD');return p.FechaPagoPeriodo<today?'Fecha vencida':p.FechaPagoPeriodo===today?'Se cumple hoy':'Próximo pago';},async openCommission(c){const selected=Object.assign({},c,{Documentos:[]});this.commissionDetail=selected;this.commissionLoading=true;try{const res=await this.axios.get(this.API+'planilla/comisiones/detalle',{params:{IdCliente:c.IdCliente,desde:this.from,hasta:this.to,idAlmacen:this.warehouse}});if(this.commissionDetail===selected)this.$set(selected,'Documentos',res.data);}catch(e){this.$toasted.error(e.response&&e.response.data.error||'No se pudo cargar el detalle.');}finally{if(this.commissionDetail===selected)this.commissionLoading=false;}},money(v){return 'S/ '+number(v).toLocaleString('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2});},matches(v){return String(v).toLowerCase().includes(this.filter.toLowerCase());},personInWarehouse(p){if(!number(this.warehouse))return true;const row=this.data.planilla.find(x=>String(x.IdPlanilla)===String(p.IdPlanilla));const person=row&&this.data.personal.find(x=>String(x.IdEmpleado)===String(row.IdEmpleado));return person&&number(person.IdAlmacen)===number(this.warehouse);},storeName(id){const a=this.data.almacenes.find(x=>number(x.IdAlmacen)===number(id));return a?a.Almacen:'Sin asignar';},isVoided(p){return number(p.Anulado)||number(p.CajaAnulado);},async load(){if(this.loading)return;if(!this.from||!this.to||this.from>this.to){this.error='Revise el rango de fechas.';return;}this.loading=true;this.error='';try{const res=await this.axios.get(this.API+'planilla/resumen',{params:{periodo:this.period,desde:this.from,hasta:this.to}});this.data=res.data;this.csrf=res.data.csrf;const c=await this.axios.get(this.API+'planilla/comisiones',{params:{desde:this.from,hasta:this.to,idAlmacen:this.warehouse}});this.commissions=c.data;this.applied=JSON.stringify([this.period,this.from,this.to,String(this.warehouse)]);}catch(e){this.error=e.response&&e.response.data.error||'No se pudo cargar el módulo.';}finally{this.loading=false;}},async post(route,body){if(this.saving)return false;this.saving=true;try{await this.axios.post(this.API+route,Object.assign({},body,{_csrf:this.csrf}));this.$toasted.success('Guardado correctamente');return true;}catch(e){this.$toasted.error(e.response&&e.response.data.error||'No se pudo guardar.');return false;}finally{this.saving=false;}},newPerson(p){this.person=p?Object.assign({},p,{Activo:!!number(p.Activo)}):{Empleado:'',DniRuc:'',Telefono:'',Cargo:'',IdAlmacen:number(this.warehouse),Sueldo:0,Regimen:'GENERAL',Pension:'NINGUNO',AFP:'',Activo:true,FechaIngreso:'',DiaPago:'',Banco:'',NumeroCuenta:'',CCI:'',Titular:''};this.advancedPerson=false;this.personModal=true;},async savePerson(){if(await this.post('planilla/personal',this.person)){this.personModal=false;await this.load();}},prepare(p){this.advanceMode=false;this.salaryAdjustment=false;const old=this.data.planilla.find(x=>String(x.IdEmpleado)===String(p.IdEmpleado));if(old){this.viewPeriod(old);return;}this.selectedEmployee=p.IdEmpleado;this.selectedName=p.Empleado;this.liquidationAccount='';this.