nt=client?null:this.personInfo(p);this.payName=client?p.Cliente:p.Empleado;this.payBalance=number(client?p.Pendiente:p.Saldo);this.pay={IdPlanilla:client?null:p.IdPlanilla,IdCliente:client?p.IdCliente:null,Tipo:client?'COMISION_CLIENTE':'SUELDO',IdCuenta:'',Fecha:this.$moment().format('YYYY-MM-DD'),Importe:'',Referencia:'',Token:'pay-'+Date.now()+'-'+Math.random().toString(36).slice(2),desde:this.from,hasta:this.to,idAlmacen:this.warehouse};this.payModal=true;},async savePay(){if(await this.post('planilla/pago',this.pay)){this.payModal=false;await this.load();}},async voidPay(p){if(!confirm('¿Anular este pago y su egreso de Caja y Banco?'))return;if(await this.post('planilla/anular',{IdPago:p.IdPago}))await this.load();},printHistory(){window.print();}}};
